import { spawn, execFile } from "node:child_process";
import { createRequire } from "node:module";
import { promisify } from "node:util";
import { createServer } from "node:net";
import {
  open,
  mkdir,
  cp,
  readFile,
  symlink,
  rm,
  access,
} from "node:fs/promises";
import { dirname, join } from "node:path";
import { homedir } from "node:os";
import { fileURLToPath } from "node:url";
import { setTimeout as delay } from "node:timers/promises";
import { privateDirectory, privateFile, sha256 } from "./private.mjs";

const exec = promisify(execFile);
const require = createRequire(import.meta.url);
const source = fileURLToPath(new URL("./display.swift", import.meta.url));
const modifiers = {
  SHIFT: 2,
  CTRL: 4,
  CONTROL: 4,
  ALT: 8,
  OPTION: 8,
  META: 16,
  CMD: 16,
  COMMAND: 16,
  SUPER: 16,
  FN: 32,
};
const aliases = {
  ENTER: "\r",
  RETURN: "\r",
  TAB: "\t",
  ESC: "\u001b",
  ESCAPE: "\u001b",
  BACKSPACE: "\u0008",
  DELETE: "\u007f",
  UP: "\uf700",
  ARROWUP: "\uf700",
  DOWN: "\uf701",
  ARROWDOWN: "\uf701",
  LEFT: "\uf702",
  ARROWLEFT: "\uf702",
  RIGHT: "\uf703",
  ARROWRIGHT: "\uf703",
  SPACE: " ",
};

export function keySequence(keys) {
  if (
    !Array.isArray(keys) ||
    !keys.length ||
    keys.some((k) => typeof k !== "string")
  )
    throw Error("Nonempty key sequence required");
  const flags = keys.reduce(
    (value, key) => value | (modifiers[key.toUpperCase()] ?? 0),
    0,
  );
  const result = keys
    .filter((k) => !modifiers[k.toUpperCase()])
    .map((k) => {
      const upper = k.toUpperCase();
      const key =
        aliases[upper] ??
        (/^F([1-9]|1[0-9]|2[0-4])$/.test(upper)
          ? String.fromCharCode(0xf703 + Number(upper.slice(1)))
          : k.length === 1
            ? k.toLowerCase()
            : null);
      if (key === null) throw Error(`Unsupported key: ${k}`);
      return { key, modifierFlags: flags };
    });
  if (!result.length) throw Error("A modifier alone is not a keypress");
  return result;
}
export function screenPoint(frame, x, y) {
  if (
    !frame ||
    !Number.isFinite(x) ||
    !Number.isFinite(y) ||
    x < 0 ||
    y < 0 ||
    x >= frame.pixelWidth ||
    y >= frame.pixelHeight
  )
    throw Error("Point outside the observed display");
  return {
    x: frame.x + (x * frame.width) / frame.pixelWidth,
    y: frame.y + (y * frame.height) / frame.pixelHeight,
  };
}
async function listen(server, port = 0) {
  await new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(port, "127.0.0.1", resolve);
  });
  return server.address().port;
}
async function freePort() {
  const server = createServer();
  const port = await listen(server);
  await new Promise((resolve) => server.close(resolve));
  return port;
}

/** Owns only its Appium process/session. No generated scripts, shell execution or remote server. */
export class AppiumDesktop {
  constructor({ outputDir, app, launch, signal }) {
    Object.assign(this, { outputDir, app, launch, signal });
  }
  async start() {
    this.signal?.throwIfAborted();
    // OS-owned lease: released even after worker death. A collision never kills another run.
    this.lease = createServer();
    try {
      await listen(this.lease, 52841);
    } catch {
      this.lease = null;
      throw Error(
        "Desktop is already controlled by another Runner (local lease port 52841)",
      );
    }
    const cache = join(homedir(), "Library", "Caches", "kaijan", "mac-runner");
    await privateDirectory(cache);
    let developer = process.env.DEVELOPER_DIR;
    if (!developer) {
      const selected = await exec("/usr/bin/xcode-select", ["-p"], {
        timeout: 5000,
        signal: this.signal,
      });
      developer = selected.stdout.trim();
      if (developer.endsWith("/CommandLineTools")) {
        const installed = "/Applications/Xcode.app/Contents/Developer";
        await access(join(installed, "usr/bin/xcodebuild"));
        developer = installed;
      }
    }
    this.environment = {
      HOME: homedir(),
      PATH: `${dirname(process.execPath)}:/usr/bin:/bin:/usr/sbin:/sbin`,
      DEVELOPER_DIR: developer,
    };
    await exec("/usr/bin/xcodebuild", ["-version"], {
      timeout: 15000,
      signal: this.signal,
      env: this.environment,
    });
    if (this.launch === false) {
      const { stdout } = await exec(
        "/usr/bin/lsappinfo",
        ["info", "-only", "pid", "-app", this.app],
        { timeout: 5000, signal: this.signal },
      );
      if (!/"?pid"?\s*=\s*[1-9]\d*/i.test(stdout))
        throw Error(
          "Target app is not running; set target.launch=true to launch it",
        );
    }
    const geometrySource = await readFile(source);
    this.geometryTool = join(
      cache,
      `display-${sha256(geometrySource).slice(0, 16)}`,
    );
    try {
      await access(this.geometryTool);
    } catch {
      await exec(
        "/usr/bin/xcrun",
        ["swiftc", source, "-o", this.geometryTool],
        { timeout: 60000, signal: this.signal, env: this.environment },
      );
    }
    const appiumRoot = dirname(require.resolve("appium/package.json"));
    const driverRoot = dirname(
      require.resolve("appium-mac2-driver/package.json"),
    );
    const runtime = join(cache, "appium-3.9.0-mac2-4.5.1");
    await privateDirectory(runtime);
    await mkdir(join(runtime, "node_modules"), {
      recursive: true,
      mode: 0o700,
    });
    // Use Appium's supported extension discovery, with dependencies from this artifact.
    for (const [name, path] of [
      ["appium", appiumRoot],
      ["appium-mac2-driver", driverRoot],
    ]) {
      const link = join(runtime, "node_modules", name);
      await rm(link, { force: true });
      await symlink(path, link, "dir");
    }
    const wda = join(runtime, "WebDriverAgentMac");
    try {
      await access(join(wda, "WebDriverAgentMac.xcodeproj"));
    } catch {
      await cp(join(driverRoot, "WebDriverAgentMac"), wda, { recursive: true });
    }
    const port = await freePort(),
      wdaPort = await freePort();
    this.base = `http://127.0.0.1:${port}`;
    this.log = await open(join(this.outputDir, "appium.log"), "wx", 0o600);
    this.child = spawn(
      process.execPath,
      [
        join(appiumRoot, "index.js"),
        "server",
        "--address",
        "127.0.0.1",
        "--port",
        String(port),
        "--use-drivers",
        "mac2",
        "--log-no-colors",
      ],
      {
        cwd: runtime,
        detached: true,
        env: { ...this.environment, APPIUM_HOME: runtime },
        stdio: ["ignore", this.log.fd, this.log.fd],
      },
    );
    this.child.on("error", (error) => {
      this.spawnError = error;
    });
    for (let i = 0; i < 120; i++) {
      this.signal?.throwIfAborted();
      if (this.spawnError) throw this.spawnError;
      if (this.child.exitCode !== null)
        throw Error("Appium exited during startup; see private appium.log");
      try {
        await this.request("GET", "/status", undefined, 1000);
        break;
      } catch (error) {
        if (i === 119) throw error;
        await delay(500, undefined, { signal: this.signal });
      }
    }
    const session = await this.request(
      "POST",
      "/session",
      {
        capabilities: {
          alwaysMatch: {
            platformName: "Mac",
            "appium:automationName": "Mac2",
            "appium:bundleId": this.app,
            "appium:noReset": true,
            "appium:skipAppKill": true,
            "appium:systemPort": wdaPort,
            "appium:systemHost": "127.0.0.1",
            "appium:bootstrapRoot": wda,
            "appium:serverStartupTimeout": 120000,
          },
          firstMatch: [{}],
        },
      },
      150000,
    );
    this.sessionId = session.sessionId;
    await privateFile(join(this.outputDir, "appium-session.json"), {
      app: this.app,
      sessionId: this.sessionId,
      port,
      wdaPort,
      pid: this.child.pid,
      versions: { appium: "3.9.0", mac2: "4.5.1" },
    });
  }
  async request(method, path, body, timeout = 30000, cleanup = false) {
    const signal =
      cleanup || !this.signal
        ? AbortSignal.timeout(timeout)
        : AbortSignal.any([this.signal, AbortSignal.timeout(timeout)]);
    const response = await fetch(`${this.base}${path}`, {
      method,
      headers: { "Content-Type": "application/json" },
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
      signal,
    });
    const result = await response.json();
    if (!response.ok || result.value?.error)
      throw Error(
        `Appium ${method} ${path}: ${result.value?.message ?? response.status}`,
      );
    return result.value;
  }
  command(name, args = {}) {
    return this.request("POST", `/session/${this.sessionId}/execute/sync`, {
      script: `macos: ${name}`,
      args: [args],
    });
  }
  async capture() {
    const { stdout } = await exec(this.geometryTool, [], {
      timeout: 5000,
      signal: this.signal,
    });
    const geometry = JSON.parse(stdout);
    const screens = await this.command("screenshots", {
      displayId: geometry.id,
    });
    const screen = screens[String(geometry.id)];
    if (!screen?.payload) throw Error("Main display screenshot unavailable");
    const bytes = Buffer.from(screen.payload, "base64");
    if (bytes.subarray(1, 4).toString() !== "PNG")
      throw Error("Appium did not return a PNG");
    this.frame = {
      ...geometry,
      pixelWidth: bytes.readUInt32BE(16),
      pixelHeight: bytes.readUInt32BE(20),
    };
    if (
      ![
        this.frame.width,
        this.frame.height,
        this.frame.pixelWidth,
        this.frame.pixelHeight,
      ].every((x) => Number.isFinite(x) && x > 0)
    )
      throw Error("Invalid display geometry");
    return { bytes, frame: this.frame };
  }
  inspect() {
    return this.request("GET", `/session/${this.sessionId}/source`);
  }
  async execute(action) {
    this.signal?.throwIfAborted();
    const point = () => {
      const result = screenPoint(this.frame, action.x, action.y);
      if (action.keys?.length) {
        if (
          !Array.isArray(action.keys) ||
          action.keys.some(
            (key) => typeof key !== "string" || !modifiers[key.toUpperCase()],
          )
        )
          throw Error("Unsupported pointer modifier");
        result.keyModifierFlags = action.keys.reduce(
          (value, key) => value | modifiers[key.toUpperCase()],
          0,
        );
      }
      return result;
    };
    switch (action.type) {
      case "click":
        if (action.button && !["left", "right"].includes(action.button))
          throw Error(`Unsupported mouse button: ${action.button}`);
        return this.command(
          action.button === "right" ? "rightClick" : "click",
          point(),
        );
      case "double_click":
        return this.command("doubleClick", point());
      case "move":
        return this.command("hover", point());
      case "scroll":
        return this.command("scroll", {
          ...point(),
          deltaX:
            ((action.scroll_x ?? 0) * this.frame.width) / this.frame.pixelWidth,
          deltaY:
            ((action.scroll_y ?? 0) * this.frame.height) /
            this.frame.pixelHeight,
        });
      case "drag": {
        if (!Array.isArray(action.path) || action.path.length !== 2)
          throw Error(
            "Mac2 supports a two-point drag; the requested path was not dispatched",
          );
        const start = screenPoint(
            this.frame,
            action.path[0].x,
            action.path[0].y,
          ),
          end = screenPoint(this.frame, action.path[1].x, action.path[1].y);
        return this.command("clickAndDrag", {
          duration: 1,
          startX: start.x,
          startY: start.y,
          endX: end.x,
          endY: end.y,
        });
      }
      case "keypress":
        return this.command("keys", { keys: keySequence(action.keys) });
      case "type":
        if (typeof action.text !== "string") throw Error("Text required");
        return this.command("keys", { keys: [...action.text] });
      case "wait":
        return delay(1500, undefined, { signal: this.signal });
      case "screenshot":
        return;
      default:
        throw Error(`Unsupported computer action: ${action.type}`);
    }
  }
  async close() {
    const receipt = {
      sessionDeleted: !this.sessionId,
      processClosed: !this.child,
      appPreserved: true,
      errors: [],
    };
    if (this.sessionId)
      try {
        await this.request(
          "DELETE",
          `/session/${this.sessionId}`,
          undefined,
          10000,
          true,
        );
        receipt.sessionDeleted = true;
      } catch (error) {
        receipt.errors.push(String(error));
      }
    if (this.child?.pid) {
      const exited = new Promise((resolve) => {
        if (this.child.exitCode !== null || this.child.signalCode !== null)
          resolve();
        else this.child.once("exit", resolve);
      });
      try {
        process.kill(-this.child.pid, "SIGTERM");
      } catch (error) {
        if (error.code !== "ESRCH") receipt.errors.push(String(error));
      }
      await Promise.race([exited, delay(5000)]);
      try {
        process.kill(-this.child.pid, "SIGKILL");
      } catch (error) {
        if (error.code !== "ESRCH") receipt.errors.push(String(error));
      }
      await Promise.race([exited, delay(2000)]);
      receipt.processClosed =
        this.child.exitCode !== null || this.child.signalCode !== null;
    }
    await this.log?.close();
    if (this.lease) await new Promise((resolve) => this.lease.close(resolve));
    return receipt;
  }
}
